# build_or_read_phylogeny() returns list(A = ..., name_map = ...)
# It uses prepR4pcm for name normalisation + 4-stage reconciliation before rotl.
phylo_out &lt;- tryCatch({
  A_path       &lt;- here::here("Rdata", "phylogeny", "proceed_A_matrix.rds")
  name_map_path &lt;- here::here("Rdata", "phylogeny", "proceed_name_map.rds")

  if (file.exists(A_path) && file.exists(name_map_path)) {
    list(A        = readRDS(A_path),
         name_map = readRDS(name_map_path))
  } else {
    message("No cached phylogeny — building via prepR4pcm + rotl ...")
    build_or_read_phylogeny(
      species_vec = unique(as.character(dat_es$sp_ncbi)),
      recompute   = FALSE
    )
  }
}, error = function(e) {
  message("Phylogeny load/build failed: ", conditionMessage(e))
  NULL
})

A_full   &lt;- phylo_out$A
name_map &lt;- phylo_out$name_map

if (!is.null(A_full)) {
  cat("Phylogenetic matrix:", nrow(A_full), "×", ncol(A_full), "\n")
} else {
  message("Phylogenetic matrix unavailable — models will omit the phylogenetic term.")
}


Phylogenetic matrix: 265 × 265 




Code
# Apply the prepR4pcm name map to dat_es ONCE here, adding sp_ncbi_canonical.
# prepare_phylo_and_data() will use this column to match rows to A.
# Rows whose sp_ncbi had no canonical match get NA in sp_ncbi_canonical and
# are excluded from the phylogenetic term (but not from other random effects).
if (!is.null(name_map)) {
  dat_es &lt;- apply_phylo_name_map(dat_es, name_map)
  n_resolved &lt;- sum(!is.na(dat_es$sp_ncbi_canonical))
  n_na_orig  &lt;- sum(is.na(dat_es$sp_ncbi) | dat_es$sp_ncbi == "")
  n_unresolved &lt;- sum(
    !is.na(dat_es$sp_ncbi) & dat_es$sp_ncbi != "" &
    is.na(dat_es$sp_ncbi_canonical)
  )
  cat("sp_ncbi_canonical coverage:\n")
  cat("  Resolved to canonical name :", n_resolved, "\n")
  cat("  Original sp_ncbi was NA/blank:", n_na_orig, "\n")
  cat("  Named but unresolved        :", n_unresolved, "\n")
} else {
  # No name map — fall back to using sp_ncbi directly
  dat_es$sp_ncbi_canonical &lt;- dat_es$sp_ncbi
  message("No name map available; using sp_ncbi as-is for phylogeny matching.")
}


